descriptor.templateCss:
/* SUNKUU 360 — Portal de Flota · CSS v3
   Tokens: --navy #00008C · --teal #00EBC8 · --bg #EBF0F7 · --brd #D4E0EE
   Cambios v3: variables :root, hardcoded→tokens, badges normalizados, uppercase auditado */

#pf-root {
  --navy: #00008C;
  --teal: #00EBC8;
  --bg:   #EBF0F7;
  --surf: #FFFFFF;
  --pri:  #0D1B2E;
  --sec:  #5A6E8A;
  --ter:  #96AABF;
  --brd:  #D4E0EE;
  --pos:  #10B981;
  --neg:  #EF4444;
  --warn: #F59E0B;
  --ind:  #6366F1;
  --shd:  0 1px 3px rgba(13,27,46,.06), 0 8px 28px rgba(13,27,46,.08);
}

*{box-sizing:border-box;margin:0;padding:0}
#pf-root{font-family:system-ui,-apple-system,'Segoe UI',sans-serif;background:var(--bg);height:100%;display:flex;flex-direction:column;transition:background .3s;overflow:hidden}

/* Cambio de fondo por capa */
#pf-root.l0{background:#E3EAF4}
#pf-root.l1{background:var(--bg)}

/* ── HEADER ──────────────────────────────────────────────── */
#pf-hdr{background:linear-gradient(135deg,var(--navy) 0%,#0a0aaa 50%,#000f72 100%);box-shadow:0 2px 14px rgba(0,0,0,.32);flex-shrink:0;z-index:20}
.pf-hi{max-width:1440px;margin:0 auto;padding:0 24px;height:56px;display:flex;align-items:center;justify-content:space-between}
.pf-hl{display:flex;align-items:center;gap:14px}
.pf-logo{display:flex;align-items:center;gap:9px;font-weight:800;font-size:17px;letter-spacing:-.01em;color:white}
.lt{color:var(--teal)}
.ls{font-weight:400;font-size:10px;color:rgba(255,255,255,.35);margin-left:4px;letter-spacing:.05em}

/* Breadcrumb */
#pf-bc{display:flex;align-items:center;gap:10px}
#btn-bc{background:rgba(255,255,255,.08);border:1px solid rgba(255,255,255,.14);border-radius:8px;padding:6px 11px;cursor:pointer;color:rgba(255,255,255,.7);font-size:11px;font-weight:600;font-family:inherit;transition:all .15s}
#btn-bc:hover{background:rgba(255,255,255,.14);color:white}
.bc-sep{width:1px;height:18px;background:rgba(255,255,255,.2)}
.bc-avatar{width:24px;height:24px;border-radius:6px;display:flex;align-items:center;justify-content:center;font-size:11px;font-weight:800;color:white;flex-shrink:0}
.bc-name{font-size:13px;font-weight:700;color:white}

/* Header right */
.pf-hr{display:flex;align-items:center;gap:12px}
.pf-online{display:flex;align-items:center;gap:6px}
.pf-odot{width:7px;height:7px;border-radius:50%;background:var(--pos);box-shadow:0 0 6px rgba(16,185,129,.7)}
#pf-online-txt{font-size:11px;color:rgba(255,255,255,.6)}
.pf-vsep{width:1px;height:22px;background:rgba(255,255,255,.1)}
.pf-user{display:flex;align-items:center;gap:9px}
.pf-uav{width:30px;height:30px;border-radius:50%;background:rgba(0,235,200,.2);border:1px solid rgba(0,235,200,.35);display:flex;align-items:center;justify-content:center;font-size:11px;font-weight:800;color:var(--teal);flex-shrink:0}
.pf-uname{font-size:11px;font-weight:600;color:white;line-height:1.2}
.pf-urole{font-size:9px;color:rgba(255,255,255,.35);line-height:1.2}

/* ── BODY ────────────────────────────────────────────────── */
#pf-body{padding:20px 24px 80px;overflow-y:auto}

/* ── ALERT RIBBON ────────────────────────────────────────── */
#pf-alert{background:rgba(239,68,68,.08);border:1px solid rgba(239,68,68,.22);border-radius:12px;padding:12px 18px;margin-bottom:16px;display:flex;align-items:center;gap:10px}
.pal-dot{width:8px;height:8px;border-radius:50%;background:var(--neg);box-shadow:0 0 6px rgba(239,68,68,.7);flex-shrink:0;animation:pulse-a 1.8s ease-in-out infinite}
@keyframes pulse-a{0%,100%{box-shadow:0 0 0 0 rgba(239,68,68,.5)}50%{box-shadow:0 0 0 5px rgba(239,68,68,0)}}
#pf-alert-txt{font-size:12px;font-weight:600;color:#991B1B;flex:1}
.pal-btn{margin-left:auto;font-size:10px;font-weight:700;color:var(--neg);background:rgba(239,68,68,.12);border:1px solid rgba(239,68,68,.28);border-radius:6px;padding:4px 10px;cursor:pointer;flex-shrink:0}

/* ── KPI BAR ─────────────────────────────────────────────── */
#pf-kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin-bottom:28px}
.pf-kpi{background:var(--surf);border-radius:16px;border:1px solid var(--brd);border-top:3px solid var(--navy);box-shadow:var(--shd);padding:18px 20px;transition:border-top-color .3s}
.pf-kpi.accent{border-top-color:var(--teal)}
/* UPPERCASE solo en labels de texto puro — sin unidades físicas */
.pk-lbl{font-size:10px;font-weight:700;color:var(--ter);letter-spacing:.06em;text-transform:uppercase;margin-bottom:10px}
.pk-val{display:flex;align-items:baseline;gap:7px;flex-wrap:wrap}
.pk-val>span:first-child{font-size:30px;font-weight:800;color:var(--pri);letter-spacing:-.04em;font-variant-numeric:tabular-nums;line-height:1}
.pk-suf{font-size:11px;font-weight:600;color:var(--navy)}
.pk-val.alert-val>span:first-child{color:var(--neg)}
.pk-val.warn-val  { color: #F59E0B; }
.pk-val.ok-val    { color: var(--teal, #00EBC8); }
.pk-val.ok-val>span:first-child{color:var(--pos)}
.pk-val.warn-val  { color: #F59E0B; }
.pk-val.ok-val    { color: var(--teal); }

/* ── CAPA 0: HEADER ──────────────────────────────────────── */
.l0-hdr{display:flex;align-items:flex-start;justify-content:space-between;margin-bottom:16px;flex-wrap:wrap;gap:10px}
.l0-title{font-size:20px;font-weight:800;color:var(--pri);letter-spacing:-.02em}
.l0-sub{font-size:12px;color:var(--ter);margin-top:4px}
.l0-total-badge{background:var(--surf);border:1px solid var(--brd);border-radius:8px;padding:8px 14px;font-size:11px;font-weight:600;color:var(--sec);align-self:center;white-space:nowrap}
.l0-total-badge span{font-size:14px;font-weight:800;color:var(--navy);margin-right:3px}

/* ── CAPA 0: FILAS DE CLIENTE ────────────────────────────── */
#client-list{display:flex;flex-direction:column;gap:10px}

.cl-row{background:var(--surf);border:1px solid var(--brd);border-radius:14px;padding:0;cursor:pointer;transition:all .2s;overflow:hidden;display:flex;align-items:stretch}
.cl-row:hover{border-color:rgba(0,235,200,.45);box-shadow:0 4px 16px rgba(0,0,0,.08);transform:translateY(-1px)}
.cl-row:hover .cr-go{color:var(--teal)}

/* Barra lateral coloreada por salud */
.cl-row-bar{width:4px;flex-shrink:0;background:var(--pos);transition:background .3s}
.cl-row-bar.atencion{background:var(--warn)}
.cl-row-bar.alerta{background:var(--neg)}

.cl-row-inner{flex:1;padding:16px 20px;display:grid;grid-template-columns:auto 1fr auto auto auto auto;align-items:center;gap:20px}

/* Identity */
.cr-id{display:flex;align-items:center;gap:12px;min-width:200px}
.cr-av{width:42px;height:42px;border-radius:10px;display:flex;align-items:center;justify-content:center;font-size:18px;font-weight:800;color:white;flex-shrink:0}
.cr-name{font-size:14px;font-weight:800;color:var(--pri)}
.cr-loc{font-size:10px;color:var(--ter);margin-top:3px}

/* ── BADGES DE ESTADO — normalizados contra Template 3EM ── */
/* Padding, font-size, border-radius, letter-spacing unificados */
.cr-health{flex-shrink:0}
.hb{display:inline-flex;align-items:center;gap:5px;padding:4px 10px;border-radius:20px;font-size:10px;font-weight:700;letter-spacing:.05em;text-transform:uppercase;white-space:nowrap}
.hb.normal  {background:rgba(16,185,129,.1);color:#065F46;border:1px solid rgba(16,185,129,.22)}
.hb.atencion{background:rgba(245,158,11,.1);color:#92400E;border:1px solid rgba(245,158,11,.22)}
.hb.alerta  {background:rgba(239,68,68,.1);color:#991B1B;border:1px solid rgba(239,68,68,.22);animation:pulse-hb 2s ease-in-out infinite}
.hb.offline {background:rgba(90,110,138,.1);color:var(--sec);border:1px solid rgba(90,110,138,.2)}
.hb.sin-datos{background:rgba(150,170,191,.1);color:var(--ter);border:1px solid rgba(150,170,191,.2)}
@keyframes pulse-hb{0%,100%{box-shadow:0 0 0 0 rgba(239,68,68,.3)}50%{box-shadow:0 0 0 4px rgba(239,68,68,0)}}

/* Stats en fila */
.cr-stats{display:flex;gap:32px;align-items:center}
.cr-stat{text-align:right}
.cr-stat-v{font-size:16px;font-weight:800;color:var(--pri);font-variant-numeric:tabular-nums;line-height:1}
.cr-stat-l{font-size:9px;color:var(--ter);margin-top:3px;white-space:nowrap}

/* Trend */
.cr-trend-wrap{flex-shrink:0;text-align:center}
.cr-trend-val{font-size:13px;font-weight:700;line-height:1}
.cr-trend-lbl{font-size:9px;color:var(--ter);margin-top:3px}

/* Meta + action */
.cr-meta{display:flex;flex-direction:column;align-items:flex-end;gap:6px;flex-shrink:0}
.cr-upd{font-size:10px;color:var(--ter);white-space:nowrap}
.cr-go{font-size:11px;font-weight:700;color:var(--navy);white-space:nowrap;transition:color .15s}

/* Placeholder row */
.cl-row.placeholder{cursor:default;background:rgba(0,0,140,.02);border:2px dashed rgba(0,0,140,.15)}
.cl-row.placeholder:hover{transform:none;box-shadow:none;border-color:rgba(0,0,140,.15)}
.cl-ph-inner{flex:1;padding:20px 24px;display:flex;align-items:center;gap:16px}
.cl-ph-icon{width:42px;height:42px;border-radius:10px;background:rgba(0,0,140,.07);border:2px dashed rgba(0,0,140,.18);display:flex;align-items:center;justify-content:center;font-size:20px;font-weight:200;color:var(--navy);flex-shrink:0}
.cl-ph-name{font-size:14px;font-weight:700;color:var(--navy)}
.cl-ph-sub{font-size:11px;color:var(--ter);margin-top:2px}
.cl-ph-badge{margin-left:auto;background:rgba(0,235,200,.08);border:1px solid rgba(0,235,200,.2);border-radius:6px;padding:5px 12px;font-size:9px;font-weight:800;color:var(--navy);letter-spacing:.08em;white-space:nowrap}

/* ── CAPA 1: CLIENT HERO ─────────────────────────────────── */
.ch-hero{background:var(--surf);border-radius:18px;border:1px solid var(--brd);box-shadow:var(--shd);padding:24px 28px;margin-bottom:28px;display:flex;align-items:center;justify-content:space-between;gap:24px;flex-wrap:wrap;border-left:5px solid var(--navy);transition:border-left-color .3s}
.ch-left{display:flex;align-items:center;gap:18px}
.ch-avatar{width:56px;height:56px;border-radius:14px;display:flex;align-items:center;justify-content:center;font-size:24px;font-weight:800;color:white;flex-shrink:0}
.ch-name{font-size:22px;font-weight:800;color:var(--pri);letter-spacing:-.02em;line-height:1}
.ch-meta{display:flex;align-items:center;gap:8px;margin-top:6px;flex-wrap:wrap}
.ch-meta>span{font-size:11px;color:var(--ter)}
.chm-sep{color:var(--brd)!important}
.ch-email{font-size:11px;color:var(--ter)}
.ch-kpis{display:flex;align-items:center;gap:0;border:1px solid var(--brd);border-radius:12px;overflow:hidden;flex-wrap:wrap}
.ch-kpi{padding:14px 22px;text-align:center}
/* Label KPI hero: texto puro, uppercase ok */
.chk-lbl{font-size:9px;font-weight:600;color:var(--ter);text-transform:uppercase;letter-spacing:.06em;margin-bottom:6px}
.chk-val{font-size:20px;font-weight:800;color:var(--pri);font-variant-numeric:tabular-nums;line-height:1}
.chk-unit{font-size:11px;font-weight:600;color:var(--sec)}
.ch-kpi-sep{width:1px;background:var(--brd);align-self:stretch}

/* ── CAPA 1: SECTION HEADER ──────────────────────────────── */
.l1-section-hdr{display:flex;align-items:baseline;gap:12px;margin-bottom:16px}
.l1-sh-title{font-size:16px;font-weight:800;color:var(--pri)}
.l1-sh-sub{font-size:12px;color:var(--ter)}

/* ── INSTALLATION GRID & CARDS ───────────────────────────── */
.inst-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}

.ic{background:var(--surf);border-radius:18px;border:1px solid var(--brd);box-shadow:var(--shd);overflow:hidden;cursor:pointer;transition:all .2s;display:flex;flex-direction:column}
.ic:not(.ic-ph):hover{transform:translateY(-3px);box-shadow:0 4px 6px rgba(13,27,46,.07),0 16px 48px rgba(13,27,46,.12);border-color:rgba(0,235,200,.4)}
.ic:hover .ic-go{color:var(--teal)}

/* Card header */
.ic-head{padding:16px 20px 12px;border-bottom:1px solid var(--brd);display:flex;align-items:flex-start;justify-content:space-between;gap:10px}
.ic-head-l{flex:1;min-width:0}
.ic-srow{display:flex;align-items:center;gap:8px;margin-bottom:5px}
.ic-dot{width:8px;height:8px;border-radius:50%;flex-shrink:0}
.ic-dot.online{background:var(--pos);box-shadow:0 0 5px rgba(16,185,129,.8)}
.ic-dot.offline{background:var(--neg)}
.ic-name{font-size:15px;font-weight:800;color:var(--pri)}
.ic-tbadge{display:inline-block;padding:3px 9px;border-radius:20px;font-size:9px;font-weight:700}
.ic-tbadge.em{background:rgba(0,0,140,.08);color:var(--navy)}
.ic-tbadge.pisc{background:rgba(99,102,241,.08);color:var(--ind)}

/* Health badge on card */
.ic-hbadge{flex-shrink:0}

/* MAIN KPI */
.ic-kpi-main{padding:18px 20px 10px;flex:1}
.ic-kpi-big{font-size:52px;font-weight:800;color:var(--pri);letter-spacing:-.04em;line-height:1;font-variant-numeric:tabular-nums}
.ic-kpi-unit{font-size:13px;font-weight:600;color:var(--sec);margin-top:4px}

/* Secondary KPIs */
.ic-kpi-sec{padding:0 20px 16px;display:grid;grid-template-columns:1fr 1fr;gap:10px}
.ics-item{background:#F4F8FC;border-radius:9px;padding:10px 12px}
/* Label secundario: texto descriptivo puro, uppercase ok */
.ics-lbl{font-size:10px;color:var(--ter);margin-bottom:3px}
.ics-val{font-size:14px;font-weight:700;color:var(--pri);font-variant-numeric:tabular-nums}

/* Sparkline */
.ic-spark{height:52px;background:#F8FAFC;border-top:1px solid #EEF2F7;border-bottom:1px solid #EEF2F7}

/* Card footer */
.ic-footer{padding:10px 20px;display:flex;justify-content:space-between;align-items:center}
.ic-last{font-size:10px;color:var(--ter)}
.ic-go{font-size:11px;font-weight:700;color:var(--navy);transition:color .15s}

/* Placeholder card */
.ic-ph{cursor:default;background:rgba(0,0,140,.02);border:2px dashed rgba(0,0,140,.15);display:flex;flex-direction:column;align-items:center;justify-content:center;padding:36px 24px;gap:10px;min-height:280px}
.ic-ph:hover{transform:none;border-color:rgba(0,0,140,.15)}
.iph-ico{width:46px;height:46px;border-radius:50%;background:rgba(0,0,140,.07);border:2px dashed rgba(0,0,140,.18);display:flex;align-items:center;justify-content:center;font-size:22px;font-weight:200;color:var(--navy)}
.iph-title{font-size:14px;font-weight:700;color:var(--navy)}
.iph-sub{font-size:10px;color:var(--ter);text-align:center;line-height:1.5}
.iph-badge{background:rgba(0,235,200,.08);border:1px solid rgba(0,235,200,.2);border-radius:6px;padding:4px 10px;font-size:9px;font-weight:800;color:var(--navy);letter-spacing:.08em}

/* ── VERSION BADGE ───────────────────────────────────────── */
.pf-vbadge{position:fixed;bottom:14px;right:14px;background:rgba(0,0,140,.85);border-radius:10px;padding:6px 12px;font-size:9px;font-weight:700;color:rgba(255,255,255,.45);letter-spacing:.1em;text-transform:uppercase;pointer-events:none}

/* ── LEGIBILIDAD: Header ── */
#pf-online-txt { font-size: 12px; color: rgba(255,255,255,.8); }
.pf-uname      { font-size: 12px; }
.pf-urole      { font-size: 10px; color: rgba(255,255,255,.55); }

/* ── LEGIBILIDAD: Capa 0 ── */
.l0-sub        { font-size: 13px; color: var(--sec); }
.l0-total-badge{ font-size: 12px; color: var(--sec); }
.l0-total-badge span { font-size: 15px; }

/* ── LEGIBILIDAD: Filas de cliente ── */
.cr-loc        { font-size: 11px; color: var(--sec); }
.cr-upd        { font-size: 11px; color: var(--sec); }
.cr-go         { font-size: 12px; }

/* ── LEGIBILIDAD: Cards de instalación ── */
.ics-lbl       { font-size: 11px; color: var(--sec); }
.chk-lbl       { font-size: 10px; color: var(--sec); }
.ic-last       { font-size: 11px; color: var(--sec); }

/* ── LEGIBILIDAD: Wizard boxes — hover igual que cards reales ── */
.cl-row.placeholder { cursor: pointer; }
.cl-row.placeholder:hover {
  transform: translateY(-1px);
  box-shadow: 0 4px 16px rgba(0,0,0,.08);
  border-color: rgba(0,235,200,.35);
}
.ic-ph { cursor: pointer; }
.ic-ph:hover {
  transform: translateY(-3px);
  box-shadow: 0 4px 6px rgba(13,27,46,.07), 0 16px 48px rgba(13,27,46,.12);
  border-color: rgba(0,235,200,.4);
}

/* ── LEGIBILIDAD: Stats en filas de cliente (capa 0) ── */
.cr-stat-v { font-size: 17px; }
.cr-stat-l { font-size: 10px; color: var(--sec); }

/* ── LEGIBILIDAD: Wizard nuevo cliente (capa 0) ── */
.cl-ph-name { font-size: 15px; }
.cl-ph-sub  { font-size: 12px; color: var(--sec); }

/* ── LEGIBILIDAD: Meta del cliente (capa 1) ── */
.ch-meta > span { font-size: 12px; color: var(--sec); }
.ch-email       { font-size: 12px; color: var(--sec); }

/* ── LEGIBILIDAD: Subtítulo sección instalaciones (capa 1) ── */
.l1-sh-sub { font-size: 13px; color: var(--sec); }

/* ── LEGIBILIDAD: Wizard nueva instalación (capa 1) ── */
.iph-title { font-size: 15px; }
.iph-sub   { font-size: 11px; color: var(--sec); }

/* ── RESPONSIVE ─────────────────────────────────────────── */
@media(max-width:1100px){
  .cl-row-inner{grid-template-columns:auto 1fr auto auto}
  .cr-trend-wrap{display:none}
}
@media(max-width:900px){
  #pf-body{padding:14px 16px 60px}
  #pf-kpis{grid-template-columns:repeat(2,1fr)}
  .inst-grid{grid-template-columns:repeat(2,1fr)}
  .cl-row-inner{grid-template-columns:auto 1fr auto}
  .cr-stats{gap:16px}
  .cr-meta{display:none}
}
@media(max-width:600px){
  .inst-grid{grid-template-columns:1fr}
  #pf-kpis{grid-template-columns:repeat(2,1fr)}
  .ch-kpis{display:none}
}

descriptor.controllerScript:
/**
 * SUNKUU 360 — Portal de Flota v2 · JavaScript
 * ThingsBoard PE 4.3.0PE
 *
 * Mejoras v2:
 *  1. Capa 0 = CRM list (filas densas) vs Capa 1 = account drill-downf9fa3680-68da-11f1-b6ce-f79957c72819
 *  2. KPI bar diferenciada por capa (gestión vs operacional)
 *  3. Health badge por instalación (NORMAL / ATENCIÓN / ALERTA)
 *  4. Alert ribbon si hay alarmas activas
 *  5. Client hero con identidad prominente en Capa 1
 *  6. Cards rediseñados: KPI principal enorme + sparkline full-width
 */
self.onInit = function () {
  var ctx = self.ctx;
  ctx.$container.css({'overflow':'hidden','height':'100%'});
  /* ── LAYOUT: usa ctx.height de TB (garantizado en px) ──── */
  function applyLayout() {
    var hdr  = el('pf-hdr');
    var body = el('pf-body');
    if (!hdr || !body) return;
    /* window.innerHeight = alto real del viewport.
       Si el widget es más alto que la pantalla, el body se limita al viewport
       → el scroll interno del body actúa → el header nunca desaparece.
       Si el widget es más pequeño que la pantalla, se usa ctx.height. */
    var viewH   = window.innerHeight;
    var widgetH = ctx.height || ctx.$container[0].offsetHeight || viewH;
    var bodyH   = Math.min(widgetH, viewH) - hdr.offsetHeight;
    body.style.height = Math.max(200, bodyH) + 'px';
  }
  setTimeout(applyLayout, 50); /* pequeño delay para que TB termine de renderizar */

  /* ── CONFIGURACIÓN CENTRAL ──────────────────────────────── */
  var CUSTOMERS = [
    {
      id:       'gocta',
      name:     'Gocta Andes Lodge',
      uuid:     '79efbf60-2ef0-11f1-a6d8-33f75efe8b97',
      letter:   'G',
      color:    'linear-gradient(135deg,#00008C,#0a0abb)',
      solid:    '#00008C',
      location: '📍 Bongará, Amazonas',
      email:    'gerenciagoctalodge@gmail.com'
    },
    {
      id:       'tucan',
      name:     'Tucán Suites Aparthotel',
      uuid:     'aa643a40-2ef0-11f1-a6d8-33f75efe8b97',
      letter:   'T',
      color:    'linear-gradient(135deg,#6366F1,#4F46E5)',
      solid:    '#6366F1',
      location: '📍 Tarapoto, San Martin',
      email:    'tucansuites1@gmail.com'
    },
    {
