  /* ── HEALTH COMPUTATION ─────────────────────────────────── */
  function computeHealth(inst) {
    var d = D[inst.id];
    /* Alarms: highest priority */
    if (d.alarmCount > 0) return { level:'alerta', text:'⚠ '+d.alarmCount+' alarma'+(d.alarmCount>1?'s':''), reason:'Alarmas activas' };
    /* Last seen */
    if (d.lastTs) {
      var age = (nowMs()-d.lastTs)/60000;
      /* Piscina: H&T G3 tiene ciclo sueño ~2h — retraso es comportamiento normal */
      if (inst.type !== 'piscina') {
        if (age > 360) return { level:'alerta',  text:'⚠ SIN SEÑAL', reason:'Sin datos hace '+Math.round(age)+' min' };
        if (age > 120) return { level:'atencion', text:'⚠ ATENCIÓN',  reason:'Sin datos hace '+Math.round(age)+' min' };
      } else {
        if (age > 1800) return { level:'alerta',  text:'⚠ SIN SEÑAL', reason:'Sin datos hace '+Math.round(age)+' min' };
        if (age > 720)  return { level:'atencion', text:'⚠ ATENCIÓN',  reason:'Sin datos hace '+Math.round(age)+' min' };
      }
    }
    /* FP check for 3EM */
    if (inst.type==='3em' && d.fp!==null) {
      if (d.fp < 0.85) return { level:'alerta',   text:'⚠ FP BAJO',   reason:'FP: '+d.fp.toFixed(2)+' — revisar cargas' };
      if (d.fp < 0.95) return { level:'atencion', text:'⚠ ATENCIÓN',  reason:'FP limitado: '+d.fp.toFixed(2) };
    }
    /* Temp check for piscina */
    if (inst.type==='piscina' && d.temp!==null) {
      if (d.temp > 35) return { level:'alerta',  text:'⚠ TEMP. ALTA', reason:'Piscina: '+fmtT(d.temp)+'°C' };
      if (d.temp < 30) return { level:'alerta',  text:'⚠ TEMP. BAJA', reason:'Piscina: '+fmtT(d.temp)+'°C' };
    }
    return { level:'normal', text:'✓ NORMAL', reason:'Operando con normalidad' };
  }

  function updateHealth(inst) {
    D[inst.id].health = computeHealth(inst);
    updateHealthDOM(inst);
    updateAlertRibbon();
