  function customerHealth(custId) {
    var insts = INSTALLATIONS.filter(function(i){return i.customer===custId;});
    var worst = 'normal';
    var worstReason = 'Operando con normalidad';
    insts.forEach(function(i){
      var h = D[i.id].health;
      if (h.level==='alerta')  { worst='alerta';   worstReason=i.name+': '+h.reason; }
      if (h.level==='atencion' && worst!=='alerta') { worst='atencion'; worstReason=i.name+': '+h.reason; }
    });
    return { level:worst, text: worst==='alerta'?'⚠ ALERTA': worst==='atencion'?'⚠ ATENCIÓN':'✓ NORMAL', reason:worstReason };
  }

