  /* ── SPARKLINE ──────────────────────────────────────────── */
  function buildSpark(data,color){
    if(!data||data.length<2) return '';
    var W=400,H=52;
    var mn=Math.min.apply(null,data),mx=Math.max.apply(null,data),rng=mx-mn||1;
    var pts=data.map(function(v,i){return[+(i/(data.length-1)*W).toFixed(1),+(H-2-((v-mn)/rng)*(H-4)).toFixed(1)];});
    var ln=pts.map(function(p,i){return(i===0?'M':'L')+p[0]+','+p[1];}).join(' ');
    var uid='g'+Math.random().toString(36).slice(2,7);
    return '<svg viewBox="0 0 '+W+' '+H+'" width="100%" height="'+H+'" preserveAspectRatio="none" style="display:block">'+
      '<defs><linearGradient id="'+uid+'" x1="0" y1="0" x2="0" y2="1">'+
      '<stop offset="0%" stop-color="'+color+'" stop-opacity=".3"/>'+
      '<stop offset="100%" stop-color="'+color+'" stop-opacity="0"/>'+
      '</linearGradient></defs>'+
      '<path d="'+ln+' L'+W+','+H+' L0,'+H+' Z" fill="url(#'+uid+')"/>'+
      '<path d="'+ln+'" fill="none" stroke="'+color+'" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/></svg>';
  }

