        var h = D[i.id].health;
        if      (h.level === 'alerta')   { riesgo++;  riesgoInst.push(i.name);  }
        else if (h.level === 'atencion') { atencion++; atencionInst.push(i.name); }
        else if (h.level === 'normal') {
          if (D[i.id].lastTs && (nowMs() - D[i.id].lastTs)/60000 > 60) sinSenal++;
          else estables++;
        } else sinSenal++;
      });
      var level, icon, borderColor, bgColor, badgeText, badgeBg, badgeColor;
      if (riesgo > 0) {
        level='riesgo';icon='error';borderColor='#EF4444';bgColor='rgba(239,68,68,.05)';badgeBg='rgba(239,68,68,.1)';badgeColor='#DC2626';badgeText='Riesgo detectado';
      } else if (atencion > 0) {
        level='atencion';icon='warning_amber';borderColor='#F59E0B';bgColor='rgba(245,158,11,.05)';badgeBg='rgba(245,158,11,.1)';badgeColor='#D97706';badgeText='Atención requerida';
      } else if (sinSenal > 0) {
        level='sin-senal';icon='signal_wifi_off';borderColor='#96AABF';bgColor='rgba(150,170,191,.05)';badgeBg='rgba(150,170,191,.1)';badgeColor='#5A6E8A';badgeText='Sin señal en '+sinSenal+(sinSenal===1?' instalación':' instalaciones');
      } else {
        level='estable';icon='check_circle';borderColor='#10B981';bgColor='rgba(16,185,129,.05)';badgeBg='#ECFDF5';badgeColor='#10B981';badgeText='Flota operativa';
      }
      var lines = [];
      if (level==='estable') {
        lines.push(total+' instalaciones monitoreadas. Todas operan dentro de los parámetros configurados.');
        lines.push('No se detectan interrupciones ni anomalías en este período.');
      } else if (level==='atencion') {
        lines.push((atencion===1?'1 instalación requiere':atencion+' instalaciones requieren')+' atención: '+atencionInst.join(', ')+'.');
        if (estables>0) lines.push(estables+(estables===1?' instalación opera':' instalaciones operan')+' con normalidad.');
        lines.push('Se recomienda revisar la evolución durante las próximas horas.');
      } else if (level==='riesgo') {
        lines.push(riesgo+(riesgo===1?' instalación presenta':' instalaciones presentan')+' riesgo operativo: '+riesgoInst.join(', ')+'.');
        if (atencion>0) lines.push(atencion+' adicional'+(atencion>1?'es':'')+' en estado de atención.');
        lines.push('Se requiere verificación inmediata.');
      } else {
        lines.push('Sin datos recientes en '+sinSenal+(sinSenal===1?' instalación.':' instalaciones.'));
        if (estables>0) lines.push(estables+(estables===1?' instalación':' instalaciones')+' operando con normalidad.');
      }
      card.innerHTML=
        '<div style="background:'+bgColor+';border:1px solid '+borderColor+'33;border-left:3px solid '+borderColor+';border-radius:10px;padding:12px 16px">'+
          '<div style="display:flex;align-items:center;gap:8px;margin-bottom:8px">'+
            '<span style="font-family:\'Material Icons\';font-size:16px;color:'+badgeColor+'">'+icon+'</span>'+
            '<span style="font-size:10px;font-weight:700;color:'+badgeColor+';text-transform:uppercase;letter-spacing:.5px">Estado de la flota hoy</span>'+
            '<span style="margin-left:auto;font-size:10px;padding:2px 8px;background:'+badgeBg+';color:'+badgeColor+';border-radius:12px;font-weight:700">'+badgeText+'</span>'+
          '</div>'+
          lines.map(function(l,i){return '<div style="font-size:12px;color:#0D1B2E;line-height:1.5;'+(i>0?'margin-top:3px;opacity:.75':'font-weight:500')+'">'+l+'</div>';}).join('')+
        '</div>';
    }

  function getFleetAttention() {
    var count=0, worstLevel='normal', worstCause='';
    INSTALLATIONS.forEach(function(i){
      var h=D[i.id].health;
      if(h.level==='alerta'){
        count++;
        if(worstLevel!=='alerta'){worstLevel='alerta';worstCause=h.reason;}
      } else if(h.level==='atencion'){
        count++;
        if(worstLevel==='normal'){worstLevel='atencion';worstCause=h.reason;}
      }
    });
    return {count:count, level:worstLevel, cause:worstCause};
  }

  function updateLayer0Aggregates() {
    var totalKW=0, totalKWH=0;
    INSTALLATIONS.forEach(function(i){
      if(D[i.id].kw!==null)  totalKW+=D[i.id].kw;
      if(D[i.id].kwh!==null) totalKWH+=D[i.id].kwh;
    });
    set('pk-v3', totalKW>0 ? totalKW.toFixed(1) : '—');
    set('pk-v4', totalKWH>0 ? 'S/. '+Math.round(totalKWH*30*0.65).toLocaleString('es-PE') : '—');
    /* Per customer */
    CUSTOMERS.forEach(function(c){
      var insts=INSTALLATIONS.filter(function(i){return i.customer===c.id;});
      var ckw=0,ckwh=0,lastTs=null;
      insts.forEach(function(i){if(D[i.id].kw!==null)ckw+=D[i.id].kw;if(D[i.id].kwh!==null)ckwh+=D[i.id].kwh;if(D[i.id].lastTs&&(!lastTs||D[i.id].lastTs>lastTs))lastTs=D[i.id].lastTs;});
      set('cr-kw-'+c.id,  ckw>0  ? ckw.toFixed(1)+' kW'   : '—');
      set('cr-kwh-'+c.id, ckwh>0 ? ckwh.toFixed(1)+' kWh' : '—');
      if(lastTs) set('cr-upd-'+c.id, timeSince(lastTs));
    });
    /* Condiciones operativas — fuente única via getFleetAttention() */
    var fa=getFleetAttention();
    set('pk-v2', fa.count>0 ? ''+fa.count : '0');
    var av2=el('pk-v2');
    if(av2) av2.parentElement.className='pk-val'+(fa.level==='alerta'?' alert-val':fa.level==='atencion'?' warn-val':' ok-val');
    var s2El=el('pk-s2');
    if(s2El){
      if(fa.count===0)      s2El.textContent='Todas operando normalmente';
      else if(fa.count===1) s2El.textContent='Principal causa: '+fa.cause;
      else                  s2El.textContent=fa.count+' requieren acción · '+fa.cause;
    }

    renderFleetState();
  }

  /* ══════════════════════════════════════════════════════════
     CAPA 1 — CLIENT ACCOUNT VIEW
  ══════════════════════════════════════════════════════════ */
  function showLayer1(cust) {
    currentLayer=1;
    selectedClient=cust;
    el('pf-root').className='l1';
    hide('layer0'); show('layer1');

    /* Breadcrumb (admin only) */
    if (!isCustomerUser && cust) {
      show('pf-bc');
      set('bc-name', cust.name);
      var bcAv=el('bc-av'); if(bcAv){bcAv.textContent=cust.letter;bcAv.style.background=cust.solid;}
      el('btn-bc').onclick=function(){showLayer0();};
    } else {
      hide('pf-bc');
    }

    var insts = cust
      ? INSTALLATIONS.filter(function(i){return i.customer===cust.id;})
      : INSTALLATIONS;

    /* Client Hero */
    if (cust) {
      var hero=el('ch-hero');
      if(hero) hero.style.borderLeftColor=cust.solid;
      var chAv=el('ch-avatar'); if(chAv){chAv.textContent=cust.letter;chAv.style.background=cust.color;}
      set('ch-name', cust.name);
      set('ch-loc',  cust.location);
      set('ch-inst', insts.length+' instalación'+(insts.length!==1?'es activas':' activa'));
      if (cust.email) { set('ch-email',cust.email); show('ch-email-sep'); show('ch-email'); }
    }

    /* Section header */
    set('l1-sh-title', 'Instalaciones'+(cust?' de '+cust.name:''));
    set('l1-sh-sub', insts.length+' instalación'+(insts.length!==1?'es activas':' activa'));

    /* KPI bar update for this client */
    renderLayer1KPIs(cust, insts);

    /* Render cards */
    renderInstCards(insts);

    /* Load data */
    loadAllData(insts);
  }

  function renderLayer1KPIs(cust, insts) {
    if(isCustomerUser){
      set('pk-lbl1','Tus instalaciones');  set('pk-s1','activas');
      set('pk-lbl2','Alertas activas');    set('pk-s2','en tu cuenta');
      set('pk-lbl3','Potencia actual');    set('pk-s3','kW combinado');
      set('pk-lbl4','Energía hoy');        set('pk-s4','kWh acumulados');
    } else {
      set('pk-lbl1','Instalaciones');      set('pk-s1','en este cliente');
      set('pk-lbl2','Estado operativo');   set('pk-s2','instalaciones monitoreadas');
      set('pk-lbl3','Potencia cliente');   set('pk-s3','kW combinado');
      set('pk-lbl4','Energía hoy');        set('pk-s4','kWh acumulados');
    }
    /* Accent teal para capa 1 */
    ['pkpi1','pkpi2','pkpi3','pkpi4'].forEach(function(id){
      var e=el(id); if(e) e.classList.add('accent');
    });
    set('pk-v1', ''+insts.length);
    var activeAlerts=insts.reduce(function(s,i){return s+(D[i.id].alarmCount||0);},0);
    set('pk-v2', ''+activeAlerts);
    var av2=el('pk-v2'); if(av2) av2.parentElement.className='pk-val'+(activeAlerts>0?' alert-val':' ok-val');
  }

  function updateLayer1Aggregates(insts) {
    var totalKW=0,totalKWH=0,lastTs=null;
    insts.forEach(function(i){
      if(D[i.id].kw!==null)  totalKW+=D[i.id].kw;
      if(D[i.id].kwh!==null) totalKWH+=D[i.id].kwh;
      if(D[i.id].lastTs&&(!lastTs||D[i.id].lastTs>lastTs)) lastTs=D[i.id].lastTs;
    });
    set('pk-v3', totalKW>0  ? totalKW.toFixed(1) : '—');
    set('pk-v4', totalKWH>0 ? totalKWH.toFixed(1) : '—');
    /* Hero KPIs */
    set('chk-kw',  totalKW>0  ? totalKW.toFixed(1)  : '—');
    set('chk-kwh', totalKWH>0 ? totalKWH.toFixed(1) : '—');
    if(lastTs) set('chk-upd', timeSince(lastTs));
    /* Estado operativo desde computeHealth() — fuente única */
    var fa2=getFleetAttention();
    /* Filtrar solo las instalaciones de este cliente */
    var scopeCount=insts.length;
    var needAction2=0, worstLevel2='normal';
    insts.forEach(function(i){
      var h=D[i.id].health;
      if(h.level==='alerta'||h.level==='atencion') needAction2++;
      if(h.level==='alerta') worstLevel2='alerta';
      else if(h.level==='atencion'&&worstLevel2==='normal') worstLevel2='atencion';
    });
    var normalCount=scopeCount-needAction2;
    var av2L1=el('pk-v2');
    if(av2L1) av2L1.parentElement.className='pk-val'+(worstLevel2==='alerta'?' alert-val':worstLevel2==='atencion'?' warn-val':' ok-val');
    if(needAction2===0){
      set('pk-v2','0');
      set('pk-s2','Todo en orden · '+scopeCount+' de '+scopeCount+' operando normalmente');
    } else {
      set('pk-v2',''+needAction2);
      set('pk-s2',(needAction2===1?'1 requiere revisión':needAction2+' requieren acción')+' · '+normalCount+' de '+scopeCount+' operando normalmente');
    }
    var achEl=el('chk-alarms');
    if(achEl){
      achEl.textContent=needAction2===0?'Todo en orden':(needAction2===1?'1 requiere revisión':needAction2+' requieren acción');
      achEl.style.color=worstLevel2==='alerta'?'#EF4444':worstLevel2==='atencion'?'#F59E0B':'#10B981';
    }
  }

  /* ── RENDER INSTALLATION CARDS ──────────────────────────── */
  function renderInstCards(insts) {
    var grid=el('inst-grid'); if(!grid) return;
    grid.innerHTML='';
    insts.forEach(function(inst){
      var isPisc=inst.type==='piscina';
      var card=document.createElement('div');
      card.className='ic';
      card.id='ic-card-'+inst.id;
      card.innerHTML=
        /* Head */
        '<div class="ic-head">'+
          '<div class="ic-head-l">'+
            '<div class="ic-srow"><div class="ic-dot '+inst.status+'"></div><span class="ic-name">'+inst.name+'</span></div>'+
            '<span class="ic-tbadge '+(isPisc?'pisc':'em')+'">'+(isPisc?'Piscina · DS18B20':'Pro 3EM · Trifásico')+'</span>'+
          '</div>'+
          '<span class="hb normal" id="ic-hb-'+inst.id+'">✓ NORMAL</span>'+
        '</div>'+
        /* Main KPI */
        '<div class="ic-kpi-main">'+
          '<div class="ic-kpi-big" id="ic-big-'+inst.id+'">—</div>'+
          '<div class="ic-kpi-unit" id="ic-unit-'+inst.id+'">'+(isPisc?'°C temperatura piscina':'kW potencia activa')+'</div>'+
        '</div>'+
        /* Secondary KPIs */
        '<div class="ic-kpi-sec">'+
          '<div class="ics-item"><div class="ics-lbl">'+(isPisc?'Calentador':'Energía hoy')+'</div><div class="ics-val" id="ic-s1-'+inst.id+'">—</div></div>'+
          '<div class="ics-item"><div class="ics-lbl">'+(isPisc?'Temperatura piscina':'Factor Pot. avg')+'</div><div class="ics-val" id="ic-s2-'+inst.id+'">—</div></div>'+
        '</div>'+
        /* Sparkline full-width */
        '<div class="ic-spark" id="ic-sp-'+inst.id+'"></div>'+
        /* Footer */
        '<div class="ic-footer"><span class="ic-last" id="ic-last-'+inst.id+'">Cargando…</span><span class="ic-go">Ver dashboard →</span></div>';

      card.addEventListener('click',function(){window.location.href='/dashboard/'+inst.dashboardId;});
      grid.appendChild(card);
    });
    /* Placeholder nueva instalación */
    var ph=document.createElement('div');
    ph.className='ic ic-ph';
    ph.innerHTML=
      '<div class="iph-ico">+</div>'+
      '<div class="iph-title">Nueva instalación</div>'+
      '<div class="iph-sub">Configuración guiada de dispositivo Shelly y dashboard</div>'+
      '<div class="iph-badge">Wizard disponible próximamente</div>';
    grid.appendChild(ph);
  }

  /* ══════════════════════════════════════════════════════════
     DATA LOADING
  ══════════════════════════════════════════════════════════ */
  function loadAllData(insts) {
    insts.forEach(function(inst){
      if (inst.type==='3em')    { load3EMLatest(inst); load3EMHealth(inst); }
      else                       { loadPiscLatest(inst); }
      loadEnergyToday(inst);
      loadEnergyYesterday(inst);
      loadAlarms(inst);
      loadSparkline(inst);
    });
  }

  function load3EMLatest(inst) {
    api(tsUrl(inst.deviceId,'potencia_activa_total',undefined,undefined,undefined,undefined,1),
      function(d){
        if(d.potencia_activa_total&&d.potencia_activa_total.length){
          D[inst.id].kw=parseFloat(d.potencia_activa_total[0].value)/1000;
          D[inst.id].lastTs=+d.potencia_activa_total[0].ts;
        }
        updateInstCard(inst);
        updateAggregates();
      });
  }

  function load3EMHealth(inst) {
    api(tsUrl(inst.deviceId,'factor_potencia_fase_a,factor_potencia_fase_b,factor_potencia_fase_c',undefined,undefined,undefined,undefined,1),
      function(d){
        var fa=d.factor_potencia_fase_a&&d.factor_potencia_fase_a.length?parseFloat(d.factor_potencia_fase_a[0].value):null;
        var fb=d.factor_potencia_fase_b&&d.factor_potencia_fase_b.length?parseFloat(d.factor_potencia_fase_b[0].value):null;
        var fc=d.factor_potencia_fase_c&&d.factor_potencia_fase_c.length?parseFloat(d.factor_potencia_fase_c[0].value):null;
        if(fa!==null&&fb!==null&&fc!==null) D[inst.id].fp=(fa+fb+fc)/3;
        /* Show FP in secondary KPI */
        if(currentLayer===1) { var s2=el('ic-s2-'+inst.id); if(s2&&D[inst.id].fp!==null) s2.textContent=D[inst.id].fp.toFixed(2); }
        updateHealth(inst);
      });
  }

  function loadPiscLatest(inst) {
    api(tsUrl(inst.deviceId,'temperatura_sonda,estado_salida',undefined,undefined,undefined,undefined,1),
      function(d){
        if(d.temperatura_sonda&&d.temperatura_sonda.length){D[inst.id].temp=parseFloat(d.temperatura_sonda[0].value);D[inst.id].lastTs=+d.temperatura_sonda[0].ts;}
        if(d.estado_salida&&d.estado_salida.length)D[inst.id].calOn=(d.estado_salida[0].value==='true'||d.estado_salida[0].value===true);
        updateInstCard(inst);
        updateAggregates();
        updateHealth(inst);
      });
  }

  function loadEnergyToday(inst) {
    if(inst.type==='piscina') return; /* piscina no tiene energía relevante en este contexto */
    api(tsUrl(inst.deviceId,'energia_total',todayStart(),nowMs(),3600000,'MAX',30),
      function(d){
        var pts=(d.energia_total||[]).map(function(p){return{ts:+p.ts,v:parseFloat(p.value)};}).sort(function(a,b){return a.ts-b.ts;});
        if(pts.length>=2){
          D[inst.id].kwh=Math.max(0,(pts[pts.length-1].v-pts[0].v)/1000);
          updateInstCard(inst);
          updateAggregates();
        }
      });
  }

  function loadAlarms(inst) {
    api('/api/alarm/DEVICE/'+inst.deviceId+'?page=0&pageSize=10&fetchOriginator=false&statusList=ACTIVE_UNACK,ACTIVE_ACK',
      function(d){
        var active=(d&&d.data)?d.data.filter(function(a){return a.status&&a.status.indexOf('ACTIVE')>=0;}).length:0;
        D[inst.id].alarmCount=active;
        updateHealth(inst);
        updateAggregates();
      },function(){D[inst.id].alarmCount=0;});
  }

  function loadEnergyYesterday(inst) {
    if (inst.type !== '3em') return;
    var ydayStart = todayStart() - 86400000;
    api(tsUrl(inst.deviceId, 'energia_total', ydayStart, todayStart(), 3600000, 'MAX', 30),
      function(d) {
        var pts = (d.energia_total || []).map(function(p) {
          return { ts: +p.ts, v: parseFloat(p.value) };
        }).sort(function(a, b) { return a.ts - b.ts; });
        if (pts.length >= 2) {
          D[inst.id].kwhYday = Math.max(0, (pts[pts.length-1].v - pts[0].v) / 1000);
        }
        updateTrend();
      }
    );
  }

  function updateTrend() {
    CUSTOMERS.forEach(function(c) {
      var insts = INSTALLATIONS.filter(function(i) { return i.customer === c.id && i.type === '3em'; });
      var todayTotal = 0, ydayTotal = 0, allReady = true;
      insts.forEach(function(i) {
        if (D[i.id].kwh !== null) todayTotal += D[i.id].kwh;
        else allReady = false;
        if (D[i.id].kwhYday !== undefined) ydayTotal += D[i.id].kwhYday;
        else allReady = false;
      });
      if (!allReady || ydayTotal === 0) return;
      var pct = ((todayTotal - ydayTotal) / ydayTotal * 100);
      var up = pct >= 0;
      var col = up ? '#EF4444' : '#10B981';
      var trendEl = el('cr-trend-' + c.id);
      var trendLbl = document.querySelector('#cl-' + c.id + ' .cr-trend-lbl');
      if (trendEl) {
        trendEl.textContent = (up ? '↑ +' : '↓ ') + Math.abs(pct).toFixed(1) + '%';
        trendEl.style.color = col;
      }
      if (trendLbl) trendLbl.style.color = '#96AABF';
    });
  }

  function loadSparkline(inst) {
    var key=inst.type==='piscina'?'temperatura_sonda':'potencia_activa_total';
    api(tsUrl(inst.deviceId,key,daysAgo(0.5),nowMs(),3600000,'AVG',12),
      function(d){
        var pts=(d[key]||[]).map(function(p){return parseFloat(p.value);});
        if(pts.length<2) return;
        D[inst.id].sparkData=pts;
        var sp=el('ic-sp-'+inst.id);
        if(sp) sp.innerHTML=buildSpark(pts,'#00EBC8');
      });
  }

  /* ── UPDATE CARD DOM ────────────────────────────────────── */
  function updateInstCard(inst) {
    var isPisc=inst.type==='piscina';
    /* Main KPI */
    var big=el('ic-big-'+inst.id);
    if(big){
      if(isPisc&&D[inst.id].temp!==null) big.textContent=fmtT(D[inst.id].temp);
      else if(!isPisc&&D[inst.id].kw!==null) big.textContent=D[inst.id].kw.toFixed(1);
    }
    /* Secondary */
    var s1=el('ic-s1-'+inst.id), s2=el('ic-s2-'+inst.id);
    if(isPisc){
      if(s1) s1.textContent=D[inst.id].calOn!==null?(D[inst.id].calOn?'Encendido':'Apagado'):'—';
      if(s2) s2.textContent=D[inst.id].temp!==null?fmtT(D[inst.id].temp)+'°C':'—';
    } else {
      if(s1) s1.textContent=D[inst.id].kwh!==null?D[inst.id].kwh.toFixed(1)+' kWh':'—';
      if(s2&&D[inst.id].fp!==null) s2.textContent=D[inst.id].fp.toFixed(2);
    }
    /* Last seen */
    var last=el('ic-last-'+inst.id);
    if(last&&D[inst.id].lastTs) last.textContent=timeSince(D[inst.id].lastTs);
  }

  /* ── AGGREGATE UPDATER ──────────────────────────────────── */
  function updateAggregates() {
    var scope=currentLayer===1&&selectedClient
      ?INSTALLATIONS.filter(function(i){return i.customer===selectedClient.id;})
      :INSTALLATIONS;
    if(currentLayer===0) updateLayer0Aggregates();
    else                 updateLayer1Aggregates(scope);
  }

  /* ── REFRESH TIMER ──────────────────────────────────────── */
  var timer=setInterval(function(){
    var scope=currentLayer===1&&selectedClient
      ?INSTALLATIONS.filter(function(i){return i.customer===selectedClient.id;})
      :INSTALLATIONS;
    scope.forEach(function(inst){
      if(inst.type==='3em') load3EMLatest(inst);
      else                  loadPiscLatest(inst);
    });
  },30000);

  self.onDestroy=function(){clearInterval(timer);};
  self.onResize  = function () { applyLayout(); };
};

